#ifndef SHIM_ZEPHYR_STORAGE_FLASH_MAP_H
#define SHIM_ZEPHYR_STORAGE_FLASH_MAP_H

#include "shim_common.h"
#include <zephyr/device.h>

/* Partition offsets/sizes (SHIM_PARTITION_OFFSET_<label>,
 * SHIM_PARTITION_SIZE_<label>) are generated by build.py from
 * Network_Beacon_nrf54/pm_static.yml into test_config.h, so the firmware's
 * own BUILD_ASSERTs compare the real partition table with the real Kconfig.
 */
#define FIXED_PARTITION_DEVICE(label) (&shim_flash_device)
#define FIXED_PARTITION_OFFSET(label) Z_SHIM_PART_OFFSET(label)
#define FIXED_PARTITION_SIZE(label) Z_SHIM_PART_SIZE(label)
#define Z_SHIM_PART_OFFSET(label) SHIM_PARTITION_OFFSET_##label
#define Z_SHIM_PART_SIZE(label) SHIM_PARTITION_SIZE_##label

#endif /* SHIM_ZEPHYR_STORAGE_FLASH_MAP_H */
